changeSet.sql:
ALTER TABLE krrg_settings
    ADD COLUMN group_id BIGINT,
    ADD COLUMN setting_type VARCHAR(20);

CREATE TABLE krrg_setting_groups ( id BIGSERIAL PRIMARY KEY, code VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, created_at TIMESTAMP, updated_at TIMESTAMP );
INSERT INTO krrg_setting_groups (code, name, created_at, updated_at) VALUES ('general', 'Общее', now(), now()), ('folder', 'Папка HR', now(), now()), ('cron', 'Крон', now(), now()), ('ai', 'ИИ', now(), now()), ('admin', 'Администрирование', now(), now()), ('gmail', 'Gmail', now(), now());
UPDATE krrg_settings s SET group_id = g.id FROM (VALUES ('first_message', 'general'), ('term', 'general'), ('folder', 'folder'), ('max_day', 'general'), ('ignore', 'general'), ('python', 'admin'), ('send_delay', 'general'), ('text_in_vacancy', 'folder'), ('cron_time', 'cron'), ('cron_lastmessage', 'cron'), ('cron_newmessage', 'cron'), ('cron_lastrun', 'cron'), ('cron_enable', 'cron'), ('ignore_if_not_found', 'admin'), ('cron_chats_count', 'cron'), ('folder_enable', 'folder'), ('add_to_folder', 'folder'), ('ai_enable', 'ai'), ('ai_api_key', 'ai'), ('ai_model', 'ai'), ('ai_vacancy_promt', 'ai'), ('resume', 'general'), ('gmail_email', 'gmail'), ('gmail_refresh_token', 'gmail'), ('gmail_subject', 'gmail') ) AS m(code, group_code) JOIN krrg_setting_groups g ON g.code = m.group_code WHERE s.code = m.code;

ALTER TABLE krrg_settings
    ADD CONSTRAINT fk_settings_group
        FOREIGN KEY (group_id) REFERENCES krrg_setting_groups (id);

ALTER TABLE krrg_settings
DROP COLUMN setting_value,
    DROP COLUMN user_id;
